import{_ as t,I as a,g as e,j as o}from"./chunks/framework.CjoWWfVe.js";const g=JSON.parse('{"title":"О разработчиках","description":"История создания ОмниКрафт ЕРП, философия ремесла и контакты мастерской N. Murashkin.","frontmatter":{"title":"О разработчиках","description":"История создания ОмниКрафт ЕРП, философия ремесла и контакты мастерской N. Murashkin.","order":18},"headers":[],"relativePath":"ru/docs/about.md","filePath":"ru/docs/about.md"}'),n={name:"ru/docs/about.md"};function s(i,r,l,h,p,u){return a(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="🛠️-о-разработчиках-от-верстака-к-коду" tabindex="-1">🛠️ О разработчиках: От верстака к коду <a class="header-anchor" href="#🛠️-о-разработчиках-от-верстака-к-коду" aria-label="Permalink to &quot;🛠️ О разработчиках: От верстака к коду&quot;">​</a></h1><p><strong>ОмниКрафт ЕРП</strong> — это не продукт безликой IT-корпорации и не очередная облачная подписка от венчурного стартапа. Эта программа родилась в пыли и запахе натуральной кожи, под стук молотка и стрекот швейных машин.</p><p>Разработчиком системы является <strong>Кожевенная мастерская Николая Мурашкина (N. Murashkin)</strong>.</p><p>🌐 <strong>Сайт мастерской:</strong> <a href="https://nmurashkin.ru" target="_blank" rel="noreferrer">nmurashkin.ru</a></p><hr><h2 id="🧵-философия-ремесла-и-кода" tabindex="-1">🧵 Философия ремесла и кода <a class="header-anchor" href="#🧵-философия-ремесла-и-кода" aria-label="Permalink to &quot;🧵 Философия ремесла и кода&quot;">​</a></h2><p>В нашей мастерской мы придерживаемся строгого правила: <strong>создавать изделия, которые будут радовать своих владельцев не одно десятилетие</strong>. Мы не гонимся за быстрой модой и одноразовыми вещами. Каждая сумка, кошелек или обложка для паспорта проектируется с расчетом на долгие годы службы, с использованием лучших сортов кожи и надежной фурнитуры.</p><p>Эту же философию «вечных ценностей» мы перенесли в разработку программного обеспечения. ОмниКрафт ЕРП создавалась как <strong>инструмент на всю жизнь</strong> для ремесленника. Мы верим, что софт для учета бизнеса должен быть:</p><ul><li><strong>Надежным:</strong> Как хороший шов вощеной нитью, программа не должна рваться в самый неподходящий момент. Архитектура базы данных (журналирование ВАЛ, ГФС-копии) гарантирует сохранность ваших цифр.</li><li><strong>Независимым:</strong> Ваши данные принадлежат только вам. Именно поэтому ОмниКрафт ЕРП работает локально на вашем компьютере (Local-First), не требует постоянного подключения к интернету и не отправляет ваши финансовые секреты на чужие серверы.</li><li><strong>Честным:</strong> Мы не заставляем вас вести бухгалтерию ради галочки. Программа говорит с вами на языке бизнес-логики, себестоимости и окупаемости времени.</li></ul><hr><h2 id="💡-почему-мы-создали-омникрафт-ерп" tabindex="-1">💡 Почему мы создали ОмниКрафт ЕРП? <a class="header-anchor" href="#💡-почему-мы-создали-омникрафт-ерп" aria-label="Permalink to &quot;💡 Почему мы создали ОмниКрафт ЕРП?&quot;">​</a></h2><p>До появления этой программы учет в мастерской велся в громоздких Excel-таблицах, блокнотах и разрозненных приложениях. Каждый раз, когда нужно было понять, <em>сколько на самом деле стоит этот рюкзак с учетом доставки кожи, износа станков и потраченных часов</em>, приходилось тратить десятки минут на рутинные вычисления.</p><p>Мы поняли, что ремесленнику нужно другое:</p><ol><li><strong>Автоматизация рутины:</strong> Программа сама должна считать МАК-себестоимость сырья, распределять логистику и начислять амортизацию.</li><li><strong>Понимание эффективности:</strong> Мастер должен видеть не просто «приход и расход», а <em>Окупаемость времени</em> (окупаемость времени) и точку безубыточности.</li><li><strong>Свобода от облаков:</strong> Мы хотели быть уверены, что в один день сервис не закроется, не поднимет цены в 10 раз и не заблокирует доступ к нашей же базе клиентов.</li></ol><p>Так родился ОмниКрафт ЕРП — умная ERP, написанная кожевниками для кожевников (и любых других ремесленников с бизнес-мышлением).</p><hr><h2 id="🤝-обратная-связь-и-сообщество" tabindex="-1">🤝 Обратная связь и сообщество <a class="header-anchor" href="#🤝-обратная-связь-и-сообщество" aria-label="Permalink to &quot;🤝 Обратная связь и сообщество&quot;">​</a></h2><p>Мы продолжаем развивать проект, опираясь на собственную практику в мастерской и потребности коллег по ремесленному цеху.</p><p>Если вы нашли ошибку в программе, хотите предложить новую функцию (например, специфический модуль для керамики или столярного дела) или просто хотите поделиться впечатлениями — мы всегда на связи.</p><ul><li><strong>Сайт и документация:</strong> <a href="https://omnicraft-erp.com" target="_blank" rel="noreferrer">omnicraft-erp.com</a></li><li><strong>Репозиторий релизов (GitHub):</strong> <a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank" rel="noreferrer">OmniCraft-ERP-Releases</a></li><li><strong>Мастерская N. Murashkin:</strong> <a href="https://nmurashkin.ru" target="_blank" rel="noreferrer">nmurashkin.ru</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Благодарность</p><p>Спасибо, что выбираете ОмниКрафт ЕРП. Мы надеемся, что эта программа снимет с вас груз рутины и подарит вам самое ценное — <strong>время</strong>. Время для творчества, для семьи и для создания вещей, которые останутся в истории.</p></div>',22)])])}const d=t(n,[["render",s]]);export{g as __pageData,d as default};
